/** @file motor.h
*
* @brief Header file for the motor control module.
*
* @details This module provides the data structures and function declarations
*          required to configure and control a motor using PWM signals
*          generated by a hardware timer.
*
* @author Julen Gallastegui de la Cruz
* @author Andrea Nieto Gil
*/

#ifndef MOTOR_MOTOR_H
#define MOTOR_MOTOR_H

/* Types --------------------------------------------------------------------*/

/**
 *
 * @brief Defines the possible rotation directions of the motor.
 */
typedef enum
{
  MOTOR_FORWARD,
  MOTOR_BACKWARD
} motor_direction_t;


/**
 *
 * @brief Represents a motor and its configuration.
 *
 * @details Stores the hardware timer, PWM channels, current speed and
 * rotation direction associated with a motor.
 */
typedef struct
{
  TIM_HandleTypeDef * timer;
  uint8_t channel_forwards;
  uint8_t channel_backwards;
  uint16_t speed;
  motor_direction_t direction;
} motor_t;

/* Public functions ---------------------------------------------------------*/

void MOTOR_Create(TIM_HandleTypeDef * timer, uint8_t channel_forwards, uint8_t channel_backwards, motor_t * output);
void MOTOR_Update(motor_t * motor, uint16_t speed, motor_direction_t direction);

#endif /* MOTOR_MOTOR_H */

/*** end of file ***/
